  const origemNav = String(h.origin || '');
  const origem = /^https?:\/\/[a-z0-9.:-]+$/i.test(origemNav)
    ? origemNav
    : (https ? 'https://' : 'http://') + String(h['x-forwarded-host'] || h.host || 'localhost').split(',')[0].trim();
